function showAdmissionSuccessModal(result, application) {
  document.querySelector(".career-success-overlay")?.remove();
  const escapeHtml = value => String(value || "—").replace(/[&<>"']/g, character => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[character]);
  const overlay = document.createElement("div");
  overlay.className = "career-success-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-labelledby", "admission-success-title");
  const colors = ["#f5c900", "#25d366", "#ffffff", "#ff7a45", "#46a7ff"];
  const confetti = Array.from({length: 56}, (_, index) => `<i style="left:${(index * 37) % 101}%;--confetti:${colors[index % colors.length]};--delay:${(index % 12) * .035}s;--duration:${1.7 + (index % 7) * .13}s;--drift:${-90 + (index * 47) % 180}px;--rotate:${(index * 31) % 180}deg"></i>`).join("");
  const reference = result.data?.id || result.applicationNo || result.id || "Submitted";
  overlay.innerHTML = `
    <div class="career-confetti" aria-hidden="true">${confetti}</div>
    <section class="career-success-modal">
      <div class="career-success-top">
        <div class="career-success-check" aria-hidden="true">✓</div>
        <small>ADMISSION ENQUIRY RECEIVED</small>
        <h2 id="admission-success-title">Submitted successfully!</h2>
        <p>${escapeHtml(result.message || "Thank you for applying. Our admissions team will contact you shortly.")}</p>
      </div>
      <div class="career-success-body">
        <div class="career-success-ref"><span>ENQUIRY REFERENCE</span>${escapeHtml(reference)}</div>
        <div class="career-success-details">
          <div class="career-success-detail"><span>Applicant</span><strong>${escapeHtml(application.name)}</strong></div>
          <div class="career-success-detail"><span>Email</span><strong>${escapeHtml(application.email)}</strong></div>
          <div class="career-success-detail"><span>Course Level</span><strong>${escapeHtml(application.level)}</strong></div>
          <div class="career-success-detail"><span>Department</span><strong>${escapeHtml(application.course)}</strong></div>
        </div>
        <button type="button" class="career-success-close">Done</button>
      </div>
    </section>`;
  const close = () => {
    document.removeEventListener("keydown", onKeydown);
    overlay.remove();
  };
  const onKeydown = event => event.key === "Escape" && close();
  overlay.querySelector(".career-success-close").addEventListener("click", close);
  overlay.addEventListener("click", event => event.target === overlay && close());
  document.addEventListener("keydown", onKeydown);
  document.body.appendChild(overlay);
  overlay.querySelector(".career-success-close").focus();
}

function showCareerSuccessModal(result, application) {
  document.querySelector(".career-success-overlay")?.remove();
  const escapeHtml = value => String(value || "—").replace(/[&<>"']/g, character => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[character]);
  const overlay = document.createElement("div");
  overlay.className = "career-success-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-labelledby", "career-success-title");
  const colors = ["#f5c900", "#25d366", "#ffffff", "#ff7a45", "#46a7ff"];
  const confetti = Array.from({length: 56}, (_, index) => `<i style="left:${(index * 37) % 101}%;--confetti:${colors[index % colors.length]};--delay:${(index % 12) * .035}s;--duration:${1.7 + (index % 7) * .13}s;--drift:${-90 + (index * 47) % 180}px;--rotate:${(index * 31) % 180}deg"></i>`).join("");
  overlay.innerHTML = `
    <div class="career-confetti" aria-hidden="true">${confetti}</div>
    <section class="career-success-modal">
      <div class="career-success-top">
        <div class="career-success-check" aria-hidden="true">✓</div>
        <small>APPLICATION RECEIVED</small>
        <h2 id="career-success-title">Submitted successfully!</h2>
        <p>Thank you for your interest in joining Sri Shakthi. Our recruitment team will review your application.</p>
      </div>
      <div class="career-success-body">
        <div class="career-success-ref"><span>APPLICATION REFERENCE</span>${escapeHtml(result.applicationNo || result.id)}</div>
        <div class="career-success-details">
          <div class="career-success-detail"><span>Applicant</span><strong>${escapeHtml(application.name)}</strong></div>
          <div class="career-success-detail"><span>Email</span><strong>${escapeHtml(application.email)}</strong></div>
          <div class="career-success-detail"><span>Position</span><strong>${escapeHtml(application.position)}</strong></div>
          <div class="career-success-detail"><span>Department</span><strong>${escapeHtml(application.department)}</strong></div>
        </div>
        <button type="button" class="career-success-close">Done</button>
      </div>
    </section>`;
  const close = () => {
    document.removeEventListener("keydown", onKeydown);
    overlay.remove();
  };
  const onKeydown = event => event.key === "Escape" && close();
  overlay.querySelector(".career-success-close").addEventListener("click", close);
  overlay.addEventListener("click", event => event.target === overlay && close());
  document.addEventListener("keydown", onKeydown);
  document.body.appendChild(overlay);
  overlay.querySelector(".career-success-close").focus();
}

if(typeof document!=="undefined"&&!window.__ACHIEVE_FILTER_INIT__){
  window.__ACHIEVE_FILTER_INIT__=true;
  document.addEventListener("click",function(e){
    const btn=e.target.closest&&e.target.closest(".lab-achieve-filter-btn");
    if(!btn)return;
    const filter=btn.getAttribute("data-filter");
    const container=btn.closest(".lab-achieve-section");
    if(!container)return;
    container.querySelectorAll(".lab-achieve-filter-btn").forEach(function(b){
      b.classList.toggle("active",b===btn);
    });
    container.querySelectorAll(".lab-achieve-card").forEach(function(card){
      const period=card.getAttribute("data-period");
      if(filter==="all"||period===filter){
        card.style.display="flex";
      }else{
        card.style.display="none";
      }
    });
  });
}
